css:
.ss-acc__i{border-top:1px solid var(--line);padding:16px 0}
.ss-acc__t{display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer;list-style:none;font:400 15px/1.5 var(--font-body);color:var(--body-text)}
.ss-acc__t::-webkit-details-marker{display:none}
.ss-acc__t::after{content:"+";flex:none;width:24px;text-align:center;font:400 22px/1 var(--font-body);color:var(--ink)}
.ss-acc__i[open] .ss-acc__t::after{content:"−"}
.ss-acc__t:focus-visible{outline:2px solid var(--accent);outline-offset:4px}
.ss-acc__d{font-size:15px;line-height:1.5;color:var(--muted);margin:8px 0 0}
